import { skyPosition, offsetFrom } from '@/lib/skyPosition';
export type CosmicScaleLevel = 1 | 2 | 3 | 4 | 5;

export type CelestialType =
  | 'star'
  | 'planet'
  | 'moon'
  | 'dwarf_planet'
  | 'asteroid'
  | 'comet'
  | 'meteor_shower'
  | 'spacecraft'
  | 'black_hole'
  | 'pulsar'
  | 'supernova'
  | 'supernova_remnant'
  | 'nebula'
  | 'star_cluster'
  | 'galaxy'
  | 'supercluster'
  | 'cosmic_structure';

export type SpectralType =
  | 'O'
  | 'B'
  | 'A'
  | 'F'
  | 'G'
  | 'K'
  | 'M'
  | 'WhiteDwarf'
  | 'Neutron'
  | 'Singularity';

export type NucleosynthesisSource =
  | 'big_bang'
  | 'cosmic_rays'
  | 'dying_low_mass_stars'
  | 'exploding_massive_stars'
  | 'exploding_white_dwarfs'
  | 'merging_neutron_stars'
  | 'synthetic';

export interface ElementAbundance {
  atomicNumber: number;
  symbol: string;
  nameEn: string;
  nameAr: string;
  percentage: number;
  roleEn?: string;
  roleAr?: string;
}

export interface CelestialBody {
  id: string;
  nameEn: string;
  nameAr: string;
  type: CelestialType;
  scaleLevel: CosmicScaleLevel;
  position: [number, number, number];
  size: number; // visual radius in relative 3D scene units
  color: string;
  emissiveColor?: string;
  spectralType?: SpectralType;
  orbitalRadius?: number;
  orbitalSpeed?: number;
  rotationSpeed?: number;
  parentBodyId?: string;
  descriptionEn: string;
  descriptionAr: string;
  distanceFromEarth: string;
  mass: string;
  radius: string;
  temperature?: string;
  primaryElements: ElementAbundance[];
  nucleosynthesisRoleEn?: string;
  nucleosynthesisRoleAr?: string;
  videoId?: string;
  imageUrl?: string;
  imageSource?: string;
}

export interface CosmicScaleInfo {
  level: CosmicScaleLevel;
  rangeMetric: string;
  nameEn: string;
  nameAr: string;
  subtitleEn: string;
  subtitleAr: string;
  cameraPosition: [number, number, number];
  cameraTarget: [number, number, number];
}

