    descriptionAr: 'المركبة الوحيدة التي زارت الكواكب العملاقة الأربعة (المشتري وزحل وأورانوس ونبتون). أُطلقت في أغسطس 1977 ودخلت الفضاء بين النجمي في نوفمبر 2018. حرف تحليقها قرب نبتون عام 1989 مسارها جنوباً: فهي تبتعد الآن بنحو 3.1 وحدة فلكية سنوياً، بزاوية 48° جنوب دائرة البروج، نحو كوكبتي الرامي والطاووس. بعد نحو 40,000 عام ستمر على بعد 1.7 سنة ضوئية من روس 248، وهو قزم أحمر في كوكبة المرأة المسلسلة يتحرك نحو الشمس، وبعد نحو 296,000 عام ستمر على بعد 4.3 سنة ضوئية من الشعرى اليمانية.',
