    descriptionAr: 'أول مركبة تعبر حزام الكويكبات وأول من حلّق قرب المشتري، في ديسمبر 1973. أُطلقت في 2 مارس 1972 وتحمل لوحة بايونير التي صممها كارل ساغان وفرانك دريك، رسالة لمن قد يعثر عليها. وصلت آخر إشارة خافتة منها إلى الأرض في 23 يناير 2003. تبتعد بنحو 2.5 وحدة فلكية سنوياً نحو العملاق الأحمر الدبران في كوكبة الثور، وستمر بجواره بعد نحو مليوني عام.',
