    radius: '1.5 light-years (equatorial ring diameter)',
    rotationSpeed: 0.005,
    descriptionEn: 'The closest observed core-collapse supernova in modern history, exploding on February 23, 1987. It is famous for its iconic "pearl ring": an equatorial circumstellar necklace of ~30-40 intensely incandescent hotspots where the expanding 10,000 km/s blast wave slammed into the gas shed by the progenitor blue supergiant Sanduleak -69 202 twenty thousand years before the explosion.',
    descriptionAr: 'أقرب مستعر أعظم ناتج عن انهيار قلب نجم يرصده البشر في العصر الحديث، انفجر في 23 فبراير 1987. يشتهر بـ "عقد اللؤلؤ" المحيط به: حلقة استوائية متألقة تضم 30-40 نقطة ساخنة براقة نتجت عن اصطدام موجة الصدمة المندفعة بسرعة 10,000 كم/ث بالغاز المقذوف قبل الانفجار بعشرين ألف عام.',
    primaryElements: [
      { atomicNumber: 26, symbol: 'Fe', nameEn: 'Synthesized Iron & Nickel-56', nameAr: 'حديد ونيكل-56 المتخلق حديثاً', percentage: 35.0, roleEn: 'Radioactive decay heat source powering ejecta', roleAr: 'مصدر حرارة التحلل الإشعاعي المغذي للحطام' },
      { atomicNumber: 28, symbol: 'Ni', nameEn: 'Nickel-56 to Cobalt-56', nameAr: 'نيكل-56 إلى كوبالت-56', percentage: 25.0, roleEn: 'Exponential light-curve decline', roleAr: 'الانخفاض الأسي للمنحنى الضوئي' },
      { atomicNumber: 8, symbol: 'O', nameEn: 'Fast Oxygen Ejecta', nameAr: 'مقذوفات أكسجين فائقة السرعة', percentage: 22.0, roleEn: 'High-speed shock knots', roleAr: 'عقد صدمية فائقة السرعة' },
      { atomicNumber: 14, symbol: 'Si', nameEn: 'Silicon & Titanium-44', nameAr: 'سيليكون وتيتانيوم-44', percentage: 18.0, roleEn: 'Deep-core explosive nucleosynthesis', roleAr: 'تخليق نووي انفجاري في القلب العميق' },
    ],
    nucleosynthesisRoleEn: 'Directly confirmed explosive nucleosynthesis: observing the radioactive decay line gamma rays of Cobalt-56 and Titanium-44 forged inside the exploding stellar core.',
    nucleosynthesisRoleAr: 'أول تأكيد رصدي مباشر للتخليق النووي الانفجاري: رصد أشعة غاما الناتجة عن تحلل كوبالت-56 وتيتانيوم-44 المصنوعين داخل قلب النجم المتفجر.',
    imageUrl: 'https://images-assets.nasa.gov/image/PIA26002/PIA26002~orig.jpg',
    imageSource: 'NASA / ESA / CSA / STScI / JWST / Mikako Matsuura (Cardiff University)',
