    radius: '≈6,500 light-years across',
    rotationSpeed: 0.003,
    descriptionEn: 'A compact elliptical satellite galaxy of Andromeda, seen just south of M31’s bright core. Discovered by Guillaume Le Gentil in 1749, it is the prototype of the rare “compact elliptical” class: its stars are packed extremely densely, and its outer stars are thought to have been stripped away by Andromeda’s tides. Its centre hosts a supermassive black hole of about 2.5 million solar masses.',
    descriptionAr: 'مجرة إهليلجية مدمجة تابعة لأندروميدا، تظهر جنوب نواة M31 الساطعة مباشرة. اكتشفها غيوم لو جنتيل عام 1749، وهي النموذج الأوّلي لفئة نادرة من المجرات تُسمّى "الإهليلجية المدمجة": نجومها متراصة بكثافة شديدة، ويُعتقد أن قوى المدّ لأندروميدا جرّدتها من نجومها الخارجية. يحتضن مركزها ثقباً أسود فائق الكتلة تبلغ كتلته نحو 2.5 مليون كتلة شمسية.',
