    radius: 'Compact iron-rich remnant, seen in silhouette against the bulge',
    descriptionEn: 'The first supernova ever observed in another galaxy. It flared up next to Andromeda’s core in August 1885 and reached about 6th magnitude — at the edge of naked-eye visibility — before fading within months. A century later its remnant was found as a small dark patch absorbing the bulge’s light in calcium and iron lines, and was later imaged by the Hubble Space Telescope. It is still the only supernova ever recorded in Andromeda.',
    descriptionAr: 'أول مستعر أعظم رُصد على الإطلاق في مجرة أخرى. توهّج بجوار نواة أندروميدا في أغسطس 1885 وبلغ القدر السادس تقريباً — على حافة الرؤية بالعين المجردة — ثم خفت خلال أشهر. وبعد قرن من الزمان عُثر على بقاياه كبقعة داكنة صغيرة تمتص ضوء الانتفاخ المركزي في خطوط الكالسيوم والحديد، ثم صوّرها تلسكوب هابل الفضائي. وما يزال المستعر الأعظم الوحيد المسجّل في أندروميدا.',
