    distanceFromEarth: '≈2.5 million light-years (Andromeda disk)',
    mass: '≈1.38 M_Sun white dwarf — close to the Chandrasekhar limit',
    radius: 'Earth-sized white dwarf inside a nova super-remnant ≈134 pc (≈440 ly) across',
    descriptionEn: 'The most frequently erupting nova known: a white dwarf in a close binary that pulls hydrogen from a companion star and ignites it in a thermonuclear flash roughly once a year. It has erupted every year since its discovery in 2008, and archival searches found earlier outbursts. Its white dwarf is close to the Chandrasekhar mass limit, making it a leading candidate to one day explode as a Type Ia supernova. Countless past eruptions have inflated a vast “nova super-remnant” shell around it (Darnley et al. 2019).',
    descriptionAr: 'أكثر المستعرات المعروفة ثوراناً: قزم أبيض في نظام ثنائي متقارب يسحب الهيدروجين من نجم مرافق ويشعله في وميض نووي حراري مرة واحدة تقريباً كل عام. ثار كل عام منذ اكتشافه عام 2008، وكشفت عمليات البحث في الأرشيف عن ثورانات أقدم. كتلة قزمه الأبيض قريبة من حد شاندراسيخار، مما يجعله مرشحاً بارزاً للانفجار يوماً ما كمستعر أعظم من النوع Ia. وقد نفخت ثوراناته التي لا تحصى قشرة هائلة من "بقايا المستعر الفائقة" حوله (دارنلي وزملاؤه 2019).',
    primaryElements: [
      { atomicNumber: 1, symbol: 'H', nameEn: 'Accreted hydrogen', nameAr: 'هيدروجين مُستقطَب', percentage: 70.0, roleEn: 'Pulled from the companion; ignites in every eruption', roleAr: 'يُسحب من النجم المرافق ويشتعل في كل ثوران' },
      { atomicNumber: 2, symbol: 'He', nameEn: 'Helium', nameAr: 'هيليوم', percentage: 28.0, roleEn: 'Ash of the hydrogen flashes, building up on the white dwarf', roleAr: 'رماد ومضات الهيدروجين المتراكم على القزم الأبيض' },
    ],
